// Jalur cadangan aset: dipakai HANYA bila lapisan aset Cloudflare tidak punya berkasnya.
// Ini jaring pengaman sementara — bukan pengganti `[assets]`. Semua berkas pub/ di-embed
// ke skrip saat build (lihat tools/siapkan-aset-embed.py), jadi tidak butuh R2 maupun
// binding tambahan. Hapus pemakaiannya setelah aset Cloudflare bisa diunggah normal lagi.

/** @type {Record<string, string>} jalur -> { tipe, b64 } */
export const BERKAS_EMBED = {"/_headers": {"tipe": "application/octet-stream","b64": ""},"/app.css": {"tipe": "text/css; charset=utf-8","b64": ""},"/app.html": {"tipe": "text/html; charset=utf-8","b64": ""},"/app.js": {"tipe": "text/javascript; charset=utf-8","b64": ""},"/d1-adapter.js": {"tipe": "text/javascript; charset=utf-8","b64": ""},"/fontawesome.css": {"tipe": "text/css; charset=utf-8","b64": ""},"/fonts.css": {"tipe": "text/css; charset=utf-8","b64": ""},"/ikon-192.png": {"tipe": "image/png","b64": ""},"/ikon-512.png": {"tipe": "image/png","b64": ""},"/logo-hade.jpg": {"tipe": "image/jpeg","b64": ""},"/tailwind.css": {"tipe": "text/css; charset=utf-8","b64": ""},"/tailwind.src.css": {"tipe": "text/css; charset=utf-8","b64": ""},"/webfonts/fa-brands-400.woff2": {"tipe": "font/woff2","b64": ""},"/webfonts/fa-regular-400.woff2": {"tipe": "font/woff2","b64": ""},"/webfonts/fa-solid-900.woff2": {"tipe": "font/woff2","b64": ""},"/webfonts/fa-v4compatibility.woff2": {"tipe": "font/woff2","b64": ""},"/webfonts/plus-jakarta-sans-latin.woff2": {"tipe": "font/woff2","b64": ""}};

const KEPALA = {
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ico': 'image/x-icon',
};

function tipe(jalur) {
  const i = jalur.lastIndexOf('.');
  return KEPALA[jalur.slice(i).toLowerCase()] || 'application/octet-stream';
}

function dariB64(s) {
  const b = atob(s);
  const u = new Uint8Array(b.length);
  for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i);
  return u;
}

// Halaman aplikasi (app.html) butuh header keamanan yang sama dengan jalur aslinya.
// Header lengkap diambil dari kode utama; di sini dipakai versi ringkas yang setara.
function sajikanHalaman() {
  const b = BERKAS_EMBED['/app.html'];
  if (!b) return null;
  return new Response(dariB64(b.b64), {
    status: 200,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store',
      'x-content-type-options': 'nosniff',
      'x-frame-options': 'DENY',
      'referrer-policy': 'same-origin',
    },
  });
}

export async function ambilBerkasCadangan(env, url) {
  let jalur = url.pathname;
  if (jalur === '/') jalur = '/app.html';
  if (jalur === '/app.html') return sajikanHalaman();
  const berkas = BERKAS_EMBED[jalur];
  if (!berkas) return null;
  return new Response(dariB64(berkas.b64), {
    status: 200,
    headers: {
      'content-type': berkas.tipe || tipe(jalur),
      'cache-control': jalur === '/app.html' ? 'no-store' : 'public, max-age=0, must-revalidate',
      'x-content-type-options': 'nosniff',
      'x-frame-options': 'DENY',
    },
  });
}
